package at.pinzker.taskloop;
import android.app.*;import android.os.*;import android.content.*;import android.view.*;import android.widget.*;import java.text.*;import java.util.*;
public class AlarmActivity extends Activity {
 Task task;int id;boolean registered;BroadcastReceiver close=new BroadcastReceiver(){public void onReceive(Context c,Intent i){if(i.getIntExtra("id",-2)==id)finish();}};
 public void onCreate(Bundle b){super.onCreate(b);getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);setShowWhenLocked(true);setTurnScreenOn(true);if(Build.VERSION.SDK_INT>=33)registerReceiver(close,new IntentFilter(getPackageName()+".CLOSE"),Context.RECEIVER_NOT_EXPORTED);else registerReceiver(close,new IntentFilter(getPackageName()+".CLOSE"));registered=true;render(getIntent());}
 protected void onNewIntent(Intent i){super.onNewIntent(i);setIntent(i);render(i);}
 void render(Intent i){id=i.getIntExtra("id",-1);task=Store.get(this,id);if(task==null||!task.active||task.last==0){finish();return;}ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.setBackgroundColor(Design.INK);LinearLayout p=Design.col(this);p.setGravity(Gravity.CENTER_VERTICAL);p.setPadding(Design.dp(this,24),Design.dp(this,20),Design.dp(this,24),Design.dp(this,20));scroll.addView(p);p.addView(Design.text(this,L.english(this)?"REMINDER":"ERINNERUNG",12,Design.LAVENDER,true));Design.gap(p,12);p.addView(Design.text(this,new SimpleDateFormat("HH:mm",Locale.getDefault()).format(new Date()),42,Design.WHITE,true));Design.gap(p,14);p.addView(Design.text(this,task.title,30,Design.WHITE,true));Design.gap(p,10);p.addView(Design.text(this,L.tr(this,task.alarmMode==1?"Lauter Alarm":task.alarmMode==2?"Nur Benachrichtigung":"Alarm"),13,Design.CORAL,true));if(!task.note.isEmpty()){Design.gap(p,12);p.addView(Design.text(this,task.note,14,Design.LAVENDER,false));}Design.gap(p,24);p.addView(Design.button(this,L.tr(this,task.kind>0&&task.doneMode==0?"Diesen Termin erledigen":"Aufgabe erledigen"),Design.LAVENDER,Design.INK,()->{Scheduler.done(this,task);finish();}));Design.gap(p,10);p.addView(Design.text(this,L.tr(this,"Verlängerungen"),13,Design.LAVENDER,true));LinearLayout snoozes=Design.row(this);int[] defaults={5,30,120};for(int x=0;x<3;x++){final int minutes=Store.prefs(this).getInt("snooze_"+x,defaults[x]);Design.weighted(snoozes,Design.button(this,minutes+L.tr(this," Min."),0xFF413451,Design.WHITE,()->{Scheduler.snooze(this,task,minutes);finish();}));}p.addView(snoozes);Design.gap(p,8);int max=Store.prefs(this).getInt("snooze_custom_max",240);max=Math.max(5,Math.min(1440,max));final int customMax=max;TextView customLabel=Design.text(this,L.tr(this,"Individuell verschieben: 30 Min."),13,Design.LAVENDER,true);p.addView(customLabel);SeekBar custom=new SeekBar(this);custom.setMax(customMax-1);custom.setProgress(Math.min(customMax-1,29));custom.setContentDescription(L.tr(this,"Individuelle Verlängerung"));p.addView(custom,new LinearLayout.LayoutParams(-1,Design.dp(this,44)));custom.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar b,int progress,boolean user){customLabel.setText(L.tr(AlarmActivity.this,"Individuell verschieben: ")+ (progress+1)+L.tr(AlarmActivity.this," Min."));}public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}});p.addView(Design.button(this,L.tr(this,"Individuell verlängern"),0xFF413451,Design.WHITE,()->{Scheduler.snooze(this,task,custom.getProgress()+1);finish();}));Design.gap(p,10);TextView permanent=Design.button(this,L.tr(this,"Aufgabe endgültig erledigen"),0xFFAF2B1E,Design.WHITE,()->{Scheduler.finish(this,task);finish();});p.addView(permanent,new LinearLayout.LayoutParams(-1,Design.dp(this,52)));if(task.kind>0){Design.gap(p,8);p.addView(Design.button(this,L.tr(this,"Nächster Termin"),0xFF413451,Design.WHITE,()->{Scheduler.skip(this,task);finish();}),new LinearLayout.LayoutParams(-1,Design.dp(this,52)));p.addView(Design.text(this,L.tr(this,"Überspringt diese Wiederholung, ohne sie als erledigt zu markieren."),12,Design.LAVENDER,false));}Design.gap(p,8);p.addView(Design.button(this,L.english(this)?"Close window":"Fenster schließen",0xFF292432,Design.WHITE,()->finish()),new LinearLayout.LayoutParams(-1,Design.dp(this,52)));Design.gap(p,8);p.addView(Design.text(this,L.english(this)?"Closing the window leaves the alarm active. Snooze stops the sound and reminds you later. Finish task permanently stops all future reminders.":"Fenster schließen lässt den Alarm aktiv. Verlängern stoppt den Ton und erinnert später erneut. Endgültiges Erledigen beendet alle weiteren Erinnerungen.",12,Design.LAVENDER,false));Design.mount(this,scroll);}
 protected void onResume(){super.onResume();Task current=Store.get(this,id);if(current==null||!current.active||current.last==0)finish();}
 protected void onDestroy(){if(registered)unregisterReceiver(close);super.onDestroy();}
}
